		/** 
		 * Tests creating a new Tag.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Tag");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Tag" );

			try {            
				Tag entity = TagService.getTagInstance().createTag( generateNewEntity() );
				thePrimaryKey = entity.getTagId();
				LOGGER.info( "-- Successfully created a Tag with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Tag. 
		 */
		public Tag testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Tag" );

			Tag entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Tag with primary key" );
			msg.append( thePrimaryKey );
			
			TagFetchOneSummary fetchOneSummary = new TagFetchOneSummary( thePrimaryKey );

			try {
				entity = TagService.getTagInstance().getTag( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Tag " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Tag.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Tag." );

			StringBuilder msg = new StringBuilder( "Failed to update a Tag : " );        
			Tag entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Tag." );

				// for use later on...
				thePrimaryKey = entity.getTagId();

				TagService proxy = TagService.getTagInstance();            
				proxy.updateTag( entity );   

				LOGGER.info( "-- Successfully saved Tag - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Tag.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Tag." );

			try{
			    Tag entity = testRead(); 
				TagService.getTagInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Tag with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Tag with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Tags.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Tags:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Tag : " );        
			List<Tag> collection  = null;

			try {
				// call the static get method on the TagService
				collection = TagService.getTagInstance().getAllTag();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Tag entity = null;            
					Iterator<Tag> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getTagId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

